G\'), (\'SNITCH - COFO - VIZAG -VISAKHAPATNAM,\',\'SNITCH - COFO - VIZAG\'), (\'SNITCH - FOCO - AJMER MITTAL\', \'SNITCH - FOCO - AJMER MITTAL\'), (\'SNITCH - FOCO - AJMER MITTAL -AJMER\', \'SNITCH - FOCO - AJMER MITTAL\'), (\'SNITCH - FOCO - C ROAD -JODHPUR\', \'SNITCH - FOCO - C ROAD JODHPUR\'), (\'SNITCH - FOCO - C ROAD JODHPUR\', \'SNITCH - FOCO - C ROAD JODHPUR\'), (\'SNITCH - FOCO - DB MALL\', \'SNITCH - FOCO - DB MALL\'), (\'SNITCH - FOCO - DB MALL -BHOPAL\', \'SNITCH - FOCO - DB MALL\'), (\'SNITCH - FOCO - EARTH EUPHORIA\', \'SNITCH - FOCO - EARTH EUPHORIA\'), (\'SNITCH - FOCO - EARTH EUPHORIA -VADODARA\', \'SNITCH - FOCO - EARTH EUPHORIA\'), (\'SNITCH - FOCO - EVA\', \'SNITCH - FOCO - EVA\'), (\'SNITCH - FOCO - EVA -VADODARA\', \'SNITCH - FOCO - EVA\'), (\'SNITCH - FOCO - GANDHI NAGAR\', \'SNITCH - FOCO - GANDHI NAGAR\'), (\'SNITCH - FOCO - GANDHI NAGAR -GANDHI NAGAR\', \'SNITCH - FOCO - GANDHI NAGAR\'), (\'SNITCH - FOCO - MBH\', \'SNITCH - FOCO - MBH\'), (\'SNITCH - FOCO - MBH -SURAT\', \'SNITCH - FOCO - MBH\'), (\'SNITCH - FOCO - SHYAMAL\', \'SNITCH - FOCO - SHYAMAL\'), (\'SNITCH - FOCO - SHYAMAL -AHMEDABAD\', \'SNITCH - FOCO - SHYAMAL\'), (\'SNITCH - FOCO - PHEONIX CITADEL\', \'SNITCH - FOCO - PHEONIX CITADEL\'), (\'SNITCH - FOCO - PHEONIX CITADEL -INDORE\', \'SNITCH - FOCO - PHEONIX CITADEL\'), (\'SNITCH - FOCO - TRION\', \'SNITCH - FOCO - TRION\'), (\'SNITCH - FOCO - TRION -VADODARA\', \'SNITCH - FOCO - TRION\'), (\'SNITCH - FOCO - VAISHALI NAGAR\', \'SNITCH - FOCO - VAISHALI NAGAR\'), (\'SNITCH - FOCO - VAISHALI NAGAR -JAIPUR\', \'SNITCH - FOCO - VAISHALI NAGAR\'), (\'SNITCH - FOCO - VR MALL\', \'SNITCH - FOCO - VR MALL\'), (\'SNITCH - FOCO - VR MALL -SURAT\', \'SNITCH - FOCO - VR MALL\'), (\'SNITCH - FOCO - YAGNIK\', \'SNITCH - FOCO - YAGNIK\'), (\'SNITCH - FOCO - YAGNIK -RAJKOT\', \'SNITCH - FOCO - YAGNIK\') AS t(raw_name, canonical_name); CREATE OR REPLACE TEMP TABLE inv_raw AS SELECT date, MARKETPLACE_MAPPED AS raw_store, UPPER(SKU_GROUP) AS sku_group, \'XS\' AS size_col, COALESCE(XS_UNITS,0) AS qty FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date >= \'2025-01-01\' UNION ALL SELECT date, MARKETPLACE_MAPPED, UPPER(SKU_GROUP), \'S\', COALESCE(S_UNITS,0) FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date >= \'2025-01-01\' UNION ALL SELECT date, MARKETPLACE_MAPPED, UPPER(SKU_GROUP), \'M\', COALESCE(M_UNITS,0) FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date >= \'2025-01-01\' UNION ALL SELECT date, MARKETPLACE_MAPPED, UPPER(SKU_GROUP), \'L\', COALESCE(L_UNITS,0) FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date >= \'2025-01-01\' UNION ALL SELECT date, MARKETPLACE_MAPPED, UPPER(SKU_GROUP), \'XL\', COALESCE(XL_UNITS,0) FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date >= \'2025-01-01\' UNION ALL SELECT date, MARKETPLACE_MAPPED, UPPER(SKU_GROUP), \'2XL\', COALESCE(XXL_UNITS,0) FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date >= \'2025-01-01\' UNION ALL SELECT date, MARKETPLACE_MAPPED, UPPER(SKU_GROUP), \'3XL\', COALESCE(XL3_UNITS,0) FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date >= \'2025-01-01\' UNION ALL SELECT date, MARKETPLACE_MAPPED, UPPER(SKU_GROUP), \'4XL\', COALESCE(XL4_UNITS,0) FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date >= \'2025-01-01\' UNION ALL SELECT date, MARKETPLACE_MAPPED, UPPER(SKU_GROUP), \'5XL\', COALESCE(XL5_UNITS,0) FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date >= \'2025-01-01\'; CREATE OR REPLACE TEMP TABLE inv_normalized AS SELECT i.date, COALESCE( m.canonical_name, REGEXP_REPLACE(REPLACE(UPPER(TRIM(i.raw_store)), \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\') ) AS store_canonical, TRIM(i.sku_group) AS sku_group, i.size_col AS size, SUM(i.qty) AS inv_qty FROM inv_raw i LEFT JOIN store_name_map m ON UPPER(TRIM(i.raw_store)) = m.raw_name GROUP BY 1,2,3,4; CREATE OR REPLACE TEMP TABLE sku_brand_tier AS SELECT DISTINCT UPPER(TRIM(sku_group)) AS sku_group, CASE WHEN l1_category = \'PLUS\' THEN \'PLUS\' ELSE \'SNITCH_LUXE\' END AS brand_tier FROM snitch_db.maplemonk.meta_mapping_cogs_sku; CREATE OR REPLACE TEMP TABLE inv_with_prior AS SELECT t.*, LAG(t.inv_qty) OVER (PARTITION BY t.store_canonical, t.sku_group, t.size ORDER BY t.date) AS prior_inv_qty FROM inv_normalized t; CREATE OR REPLACE TEMP TABLE pivotal_check AS SELECT p.store_canonical, p.sku_group, p.date, b.brand_tier, COUNT(*) AS pivotal_size_count, SUM(CASE WHEN p.prior_inv_qty IS NOT NULL AND p.inv_qty > p.prior_inv_qty THEN 1 ELSE 0 END) AS pivotal_sizes_increased FROM inv_with_prior p JOIN sku_brand_tier b ON p.sku_group = b.sku_group WHERE (p.size IN (\'S\',\'M\',\'L\',\'XL\') AND b.brand_tier = \'SNITCH_LUXE\') OR (p.size IN (\'3XL\',\'4XL\',\'5XL\') AND b.brand_tier = \'PLUS\') GROUP BY 1,2,3,4; CREATE OR REPLACE TEMP TABLE reallocation_flags AS SELECT store_canonical, sku_group, date, brand_tier, CASE WHEN brand_tier = \'SNITCH_LUXE\' AND pivotal_size_count = 4 AND pivotal_sizes_increased = 4 THEN 1 WHEN brand_tier = \'PLUS\' AND pivotal_size_count = 3 AND pivotal_sizes_increased = 3 THEN 1 ELSE 0 END AS is_reallocation FROM pivotal_check; CREATE OR REPLACE TEMP TABLE first_avail AS SELECT store_canonical, sku_group, MIN(date) AS cp1_date FROM inv_normalized WHERE inv_qty > 0 GROUP BY 1,2; CREATE OR REPLACE TEMP TABLE reallocation_ranked AS SELECT r.store_canonical, r.sku_group, r.date AS cp_date, ROW_NUMBER() OVER (PARTITION BY r.store_canonical, r.sku_group ORDER BY r.date) AS realloc_rank FROM reallocation_flags r JOIN first_avail f ON r.store_canonical = f.store_canonical AND r.sku_group = f.sku_group WHERE r.is_reallocation = 1 AND r.date > f.cp1_date; CREATE OR REPLACE TEMP TABLE checkpoints AS SELECT store_canonical, sku_group, 1 AS cp_num, cp1_date AS cp_date FROM first_avail UNION ALL SELECT store_canonical, sku_group, realloc_rank + 1, cp_date FROM reallocation_ranked WHERE realloc_rank <= 3; CREATE OR REPLACE TEMP TABLE sales_raw_filtered AS SELECT date, channel AS raw_store, UPPER(TRIM(sku_group)) AS sku_group, gross_quantity::INT AS qty_sold FROM snitch_db.maplemonk.horizontal_sales_categories WHERE LOWER(type) LIKE \'store%\' AND date >= \'2025-01-01\'; CREATE OR REPLACE TEMP TABLE sales_normalized AS SELECT COALESCE( m.canonical_name, REGEXP_REPLACE(REPLACE(UPPER(TRIM(s.raw_store)), \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\') ) AS store_canonical, s.sku_group, s.date, SUM(s.qty_sold) AS qty_sold FROM sales_raw_filtered s LEFT JOIN store_name_map m ON UPPER(TRIM(s.raw_store)) = m.raw_name GROUP BY 1,2,3; CREATE OR REPLACE TEMP TABLE checkpoint_ros AS SELECT c.store_canonical, c.sku_group, c.cp_num, c.cp_date, w.window_days, ROUND(SUM(s.qty_sold) / NULLIF(COUNT(DISTINCT s.date), 0), 2) AS ros FROM checkpoints c CROSS JOIN (SELECT 5 AS window_days UNION ALL SELECT 7 UNION ALL SELECT 10 UNION ALL SELECT 15 UNION ALL SELECT 30) w LEFT JOIN sales_normalized s ON s.store_canonical = c.store_canonical AND s.sku_group = c.sku_group AND s.date >= c.cp_date AND s.date < DATEADD(day, w.window_days, c.cp_date) GROUP BY 1,2,3,4,5; SELECT store_canonical, sku_group, MAX(CASE WHEN cp_num=1 THEN cp_date END) AS cp1_date, MAX(CASE WHEN cp_num=1 AND window_days=5 THEN ros END) AS cp1_ros5d, MAX(CASE WHEN cp_num=1 AND window_days=7 THEN ros END) AS cp1_ros7d, MAX(CASE WHEN cp_num=1 AND window_days=10 THEN ros END) AS cp1_ros10d, MAX(CASE WHEN cp_num=1 AND window_days=15 THEN ros END) AS cp1_ros15d, MAX(CASE WHEN cp_num=1 AND window_days=30 THEN ros END) AS cp1_ros30d, MAX(CASE WHEN cp_num=2 THEN cp_date END) AS cp2_date, MAX(CASE WHEN cp_num=2 AND window_days=5 THEN ros END) AS cp2_ros5d, MAX(CASE WHEN cp_num=2 AND window_days=7 THEN ros END) AS cp2_ros7d, MAX(CASE WHEN cp_num=2 AND window_days=10 THEN ros END) AS cp2_ros10d, MAX(CASE WHEN cp_num=2 AND window_days=15 THEN ros END) AS cp2_ros15d, MAX(CASE WHEN cp_num=2 AND window_days=30 THEN ros END) AS cp2_ros30d, MAX(CASE WHEN cp_num=3 THEN cp_date END) AS cp3_date, MAX(CASE WHEN cp_num=3 AND window_days=5 THEN ros END) AS cp3_ros5d, MAX(CASE WHEN cp_num=3 AND window_days=7 THEN ros END) AS cp3_ros7d, MAX(CASE WHEN cp_num=3 AND window_days=10 THEN ros END) AS cp3_ros10d, MAX(CASE WHEN cp_num=3 AND window_days=15 THEN ros END) AS cp3_ros15d, MAX(CASE WHEN cp_num=3 AND window_days=30 THEN ros END) AS cp3_ros30d, MAX(CASE WHEN cp_num=4 THEN cp_date END) AS cp4_date, MAX(CASE WHEN cp_num=4 AND window_days=5 THEN ros END) AS cp4_ros5d, MAX(CASE WHEN cp_num=4 AND window_days=7 THEN ros END) AS cp4_ros7d, MAX(CASE WHEN cp_num=4 AND window_days=10 THEN ros END) AS cp4_ros10d, MAX(CASE WHEN cp_num=4 AND window_days=15 THEN ros END) AS cp4_ros15d, MAX(CASE WHEN cp_num=4 AND window_days=30 THEN ros END) AS cp4_ros30d FROM checkpoint_ros GROUP BY store_canonical, sku_group ORDER BY store_canonical, sku_group;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
